import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import {
  type TextareaContextType,
  type TextareaProps,
  type TextareaCharCountProps,
} from "./textarea.types";
import { TextareaContext, useTextarea } from "./hooks/use-textarea";
import { useAriaDescribedBy } from "./hooks/use-aria-described-by";
import { useTextareaState } from "./hooks/use-textarea-state";
import { TextareaClasses, StyledTextarea } from "./textarea.styles";

const defaultGetItemAriaLabel = (currentLength: number, maxLength: number): string =>
  `${currentLength} out of ${maxLength} characters used`;

const TextareaRoot = forwardRef<HTMLTextAreaElement, TextareaProps>((props, ref) => {
  const {
    variant = "default",
    size = "default",
    resize = "both",
    placeholder,
    rows,
    maxLength,
    className,
    restrictCharacterCount,
    children,
    id,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    defaultValue,
    ...rest
  } = props;
  const theme = useTheme();
  const {
    textareaId: generatedTextareaId,
    currentValue,
    handleChange,
    addAriaDescribedBy,
    removeAriaDescribedBy,
    getAriaDescribedBy,
  } = useTextareaState(props);
  const textareaId = id || generatedTextareaId;

  const contextValue: TextareaContextType = {
    textareaId,
    value: currentValue,
    maxLength,
    restrictCharacterCount,
    addAriaDescribedBy,
    removeAriaDescribedBy,
  };

  const textareaElementClasses = clsx(TextareaClasses.input, className, {
    [TextareaClasses.sm]: size === "sm",
    [TextareaClasses.resizeHorizontal]: resize === "horizontal",
    [TextareaClasses.resizeVertical]: resize === "vertical",
    [TextareaClasses.resizeNone]: resize === "none",
  });

  return (
    <TextareaContext.Provider value={contextValue}>
      <StyledTextarea
        className={TextareaClasses.root}
        currentTheme={theme}
        styleSlots={props.styleSlots}
        variant={variant}
      >
        <textarea
          {...rest}
          ref={ref}
          aria-describedby={getAriaDescribedBy}
          className={textareaElementClasses}
          id={textareaId}
          maxLength={restrictCharacterCount ? maxLength : undefined}
          placeholder={placeholder}
          rows={rows}
          value={currentValue}
          onChange={handleChange}
        />
        {children}
      </StyledTextarea>
    </TextareaContext.Provider>
  );
});

TextareaRoot.displayName = "Textarea";

const CharCount: React.FC<TextareaCharCountProps> = ({
  getItemAriaLabel: customGetItemAriaLabel,
  "aria-hidden": ariaHidden,
  render,
  ...props
}) => {
  const { value, maxLength, textareaId } = useTextarea();
  const charCountId = `${textareaId}-character-count`;
  const labelGetter = customGetItemAriaLabel || defaultGetItemAriaLabel;
  useAriaDescribedBy({ id: charCountId, "aria-hidden": ariaHidden });

  if (!maxLength) {
    return null;
  }

  const charCountProps = {
    "aria-label": labelGetter(value.length, maxLength),
    "aria-live": "polite" as const,
    className: clsx(TextareaClasses.characterCount, {
      [TextareaClasses.characterCountWarning]: value.length >= Number(maxLength),
    }),
    id: charCountId,
    ...props,
  };

  if (render) {
    const rendered = render(value.length, maxLength);
    if (React.isValidElement(rendered)) {
      return React.cloneElement(rendered as React.ReactElement, {
        ...charCountProps,
        className: clsx(charCountProps.className, rendered.props.className),
      });
    } else {
      throw new Error("Textarea.CharCount render prop must return a valid React element");
    }
  }

  return (
    <div {...charCountProps}>
      {value.length}/{maxLength}
    </div>
  );
};
CharCount.displayName = "Textarea.CharCount";

const Textarea = Object.assign(TextareaRoot, {
  CharCount,
});

export default Textarea;
